'use strict';

// Generated by tool/build_web.py. Cache names are isolated by app path.
const PREFIX = `foco-de-teste:${self.registration.scope}:`;
const CACHE = `${PREFIX}__VERSION__`;
const RESOURCES = __RESOURCES__;
const ROOT = new URL(self.registration.scope);

self.addEventListener('install', (event) => {
  // Do not skipWaiting: a new release must not replace an active study session.
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    await cache.addAll(RESOURCES.map((path) =>
      new Request(new URL(path, ROOT), {cache: 'reload'})));
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const name of await caches.keys()) {
      if (name.startsWith(PREFIX) && name !== CACHE) await caches.delete(name);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);
  if (event.request.method !== 'GET' || url.origin !== ROOT.origin ||
      !url.pathname.startsWith(ROOT.pathname)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    if (event.request.mode === 'navigate') {
      return (await cache.match(new URL('index.html', ROOT))) || fetch(event.request);
    }
    // Ignore query strings on bundled files; never cache arbitrary runtime data.
    return (await cache.match(event.request, {ignoreSearch: true})) || fetch(event.request);
  })());
});
